func:
msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;

/**
 * Builds a notification payload for the source client.
 * Only reached after a successful POST when issues need reporting.
 */
const notification = {
    payload: {
        entry_id: msg.entry.id,
        failed_files: msg.metadata.files.failed,
        entry_author: msg.entry.author,
        metadata: msg.metadata
    }
};

return notification;

const geo = msg.metadata?.geo;
if (!geo) return [null, null, msg]; // Output 3 → no geo → Return response

if (geo.type === "mapFeatures") {
    return [msg, null, null]; // Output 1 → Geo Artifacts (unused)
}
return [null, msg, null]; // Output 2 → Markers → POST WaSOS geo

const geo = msg.metadata?.geo;

if (geo && geo.type === "mapFeatures") {
    msg._chat_payload = Object.assign({}, msg.payload);
    return [msg, null];
}

return [null, msg];

const preview = msg._artifact_preview;
const payload = msg._chat_payload;
if (!payload) return null;

const source = msg.metadata.source;
const logName = source.name || source.client_specific?.log_name || "Ukjent";

if (preview) {
    const verb = preview.action === "create" ? "La til" : "oppdaterte";
    payload.content = "[" + source.client_system + " - " + logName + "] "
        + verb + " " + (preview.name || "objekt") + " på kartet";
    payload.isLocation = true;
    payload.data = {
        kind: "artifact",
        uuid: preview.uuid,
        uri: "/api/geo/artifacts/" + preview.uuid
    };
} else {
    payload.content = "[" + source.client_system + " - " + logName + "] "
        + "fjernet objekt fra kartet";
}

msg.payload = payload;
delete msg.metadata.geo;
delete msg._chat_payload;
delete msg._artifact_preview;

return msg;
